import React, { useEffect, useState } from "react";

type Business = {
  _id: string;
  businessName?: string;
  description?: string;
  city?: string;
  imageUrl?: string;
};

const SingleSalonTest: React.FC = () => {
  const [salon, setSalon] = useState<Business | null>(null);

  useEffect(() => {
    const fetchOne = async () => {
      try {
        const res = await fetch("http://localhost:5000/api/public/businesses");
        const data = await res.json();

        // adjust based on your API shape
        const list: Business[] = Array.isArray(data)
          ? data
          : data.businesses || [];

        console.log("API salons:", list);

        if (list.length > 0) {
          setSalon(list[0]); // just take the first one for testing
        }
      } catch (err) {
        console.error("Error fetching salons:", err);
      }
    };

    fetchOne();
  }, []);

  if (!salon) {
    return <div>Loading first salon...</div>;
  }

  const imgSrc = salon.imageUrl
    ? `http://localhost:5000${salon.imageUrl}`
    : null;

  return (
    <div style={{ padding: 20 }}>
      <h1>Single Salon Image Test</h1>

      <pre
        style={{
          background: "#f4f4f4",
          padding: 10,
          borderRadius: 4,
          maxWidth: 600,
          overflowX: "auto",
        }}
      >
        {JSON.stringify(salon, null, 2)}
      </pre>

      <div style={{ marginTop: 20 }}>
        <p>
          <strong>imageUrl field:</strong> {salon.imageUrl || "(none)"}
        </p>

        {imgSrc ? (
          <>
            <p>
              <strong>Full image URL used:</strong> {imgSrc}
            </p>
            <img
              src={imgSrc}
              alt={salon.businessName || "Salon image"}
              style={{ width: 300, height: 200, objectFit: "cover" }}
            />
          </>
        ) : (
          <p style={{ color: "red" }}>This salon has no imageUrl in the DB.</p>
        )}
      </div>
    </div>
  );
};

export default SingleSalonTest;
